package org.slavicmyths.verify.client;
import java.nio.file.*;import java.util.*;
import net.minecraft.client.*;
import org.slavicmyths.sivka.*;
/** Real client key bindings -> production packet sender -> actual integrated server. No desktop input. */
public final class Controls269 {
 public static boolean started,done,driving;static int t;static long start;static double y0,peak;static final List<Map<String,Object>> checks=new ArrayList<>();static final Map<String,Object> out=new LinkedHashMap<>();static final Set<String> shots=new HashSet<>();static final Path O=Path.of("../../docs/implementation/stabilization269-20261026/"+(Client269.RESUME?"client-relogin":"client-controls"));
 static void check(boolean ok,String label){checks.add(Map.of("status",ok?"PASS":"FAIL","test",label));System.out.println("QA269_CLIENT "+(ok?"PASS ":"FAIL ")+label);}
 static void keys(Minecraft mc,boolean up,boolean sprint,boolean jump,boolean left,boolean down){mc.options.keyUp.setDown(up);mc.options.keySprint.setDown(sprint);mc.options.keyJump.setDown(jump);mc.options.keyLeft.setDown(left);org.slavicmyths.client.SivkaClient.DOWN.setDown(down);}
 public static void finish(Throwable error){if(done)return;done=true;driving=false;var mc=Minecraft.getInstance();keys(mc,false,false,false,false,false);try{out.put("checks",checks);out.put("status",error==null&&checks.stream().noneMatch(x->x.get("status").equals("FAIL"))?"PASS_CLIENT_AUTOMATED":"FAIL");out.put("error",error==null?null:error.toString());out.put("manual_keyboard","NOT_RUN; actual KeyMapping states set by QA, production sender/receiver untouched");out.put("network_MP","NOT_RUN; one actual client with integrated server");Files.createDirectories(O);Files.writeString(O.resolve("receipt.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));if(error!=null)error.printStackTrace();}catch(Exception ex){ex.printStackTrace();}mc.stop();}
 public static void tick(Minecraft mc){if(done)return;try{
  if(!started){started=true;start=System.nanoTime();Client269.ready=true;out.put("master_volume",mc.options.getSoundSourceOptionInstance(net.minecraft.sounds.SoundSource.MASTER).get());out.put("GLFW_visible",org.lwjgl.glfw.GLFW.glfwGetWindowAttrib(mc.getWindow().getWindow(),org.lwjgl.glfw.GLFW.GLFW_VISIBLE));mc.options.setCameraType(CameraType.THIRD_PERSON_BACK);mc.setScreen(null);
   if(!Client269.RESUME)mc.getSingleplayerServer().execute(()->{try{var p=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();var w=p.serverLevel();for(int z=-1;z<=16;z++){w.getChunk(62,z);w.setChunkForced(62,z,true);}for(int z=120;z<=256;z++)for(int x=996;x<=1005;x++)w.setBlock(new net.minecraft.core.BlockPos(x,200,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),2);p.stopRiding();p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setNoGravity(true);p.teleportTo(w,1000.5,201,2.5,0,0);var h=SivkaContent.ENTITY.get().create(w);h.moveTo(1000.5,201,2.5,0,0);var bond=new SivkaBonds.Bond(p.getUUID());bond.stage=7;bond.entity=h.getUUID();SivkaBonds.get(w).bonds.put(p.getUUID(),bond);SivkaBonds.get(w).setDirty();h.owner=p.getUUID();h.bond=bond.id;h.generation=bond.generation;w.addFreshEntity(h);p.startRiding(h,true);Client269.horse=h;}catch(Throwable ex){mc.execute(()->finish(ex));}});
  }
  if(System.nanoTime()-start>180_000_000_000L)throw new IllegalStateException("client control timeout");
  if(Client269.RESUME){t++;if(t==60){var serverPlayer=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();check(mc.player.getVehicle() instanceof SivkaEntity,"actual client login restores Sivka vehicle");check(serverPlayer.getVehicle() instanceof SivkaEntity,"actual vanilla server login restores RootVehicle");if(serverPlayer.getVehicle() instanceof SivkaEntity h){Client269.horse=h;var previous=new com.google.gson.Gson().fromJson(Files.readString(Path.of("../../docs/implementation/stabilization269-20261026/client-controls/receipt.json")),com.google.gson.JsonObject.class);check(h.getUUID().toString().equals(previous.get("saved_horse_uuid").getAsString())&&h.owns(serverPlayer),"same UUID and owner after real client process restart");check(h.flying(),"saved airborne state survives real client process restart");}finish(null);}return;}
  if(Client269.horse==null||!(mc.player.getVehicle() instanceof SivkaEntity))return;var h=Client269.horse;t++;driving=true;peak=Math.max(peak,h.getY());if(t==1){y0=h.getY();peak=y0;check(mc.player.getVehicle().getUUID().equals(h.getUUID()),"actual client tracks canonical server mount");}
  keys(mc,t>=90&&t<220,t>=90&&t<220,t>=40&&t<44||t>=90&&t<96,t>=300&&t<325,t>=340&&t<400);
  if(t==80){out.put("ground_jump_peak",peak-y0);check(peak-y0>=1.1,"real client Space key binding jumps over one block without saddle");}
  if(t==112)check(h.flying(),"real client Sprint+W+Space packets take off quickly");
  if(t==210){out.put("client_flight_speed",((SivkaEntity)mc.player.getVehicle()).actualSpeed());out.put("server_flight_speed",h.actualSpeed());check(h.actualSpeed()>=39,"actual client forward input reaches server40blocks/s");check(((SivkaEntity)mc.player.getVehicle()).actualSpeed()>=35,"actual client receives flight speed sync");}
  if(t==265){out.put("hover_speed",h.actualSpeed());check(h.actualSpeed()<.5&&h.flying(),"real client release keys brakes to airborne hover");mc.player.setYRot(90);}
  if(t==290)check(Math.abs(net.minecraft.util.Mth.wrapDegrees(h.getYRot()-90))<2,"actual client yaw packet steers server horse");
  if(t==299)out.put("strafe_z_before",h.getZ());if(t==330){out.put("strafe_z_after",h.getZ());check(Math.abs(h.getZ()-((Number)out.get("strafe_z_before")).doubleValue())>2,"actual client A key produces lateral displacement");check(Math.abs(net.minecraft.util.Mth.wrapDegrees(h.getYRot()-90))<2,"strafe does not autonomously turn mount");}
  if(t==415)check(!h.flying()&&h.onGround(),"real client descend binding lands safely on platform");
  if(t==440)mc.getSingleplayerServer().execute(()->{var n=new net.minecraft.nbt.CompoundTag();h.addAdditionalSaveData(n);n.putBoolean("SivkaAirborne",true);h.readAdditionalSaveData(n);h.setPos(1000.5,211,2.5);});
  if(t==470){out.put("saved_horse_uuid",h.getUUID().toString());check(mc.player.getVehicle()!=null&&h.flying(),"client exits mounted and airborne for genuine relog scenario");finish(null);}
 }catch(Throwable error){finish(error);}}
 public static void capture(Minecraft mc){if(done||t==0)return;String name=t>=405&&t<=425?"landing":t>=200&&t<=215?"flight":t>=55&&t<=70?"jump":null;if(name==null||!shots.add(name))return;try{Files.createDirectories(O);try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(O.resolve(name+".png"));}}catch(Exception ex){finish(ex);}}
}
